import pages as PG
from pages import *
from pages import foreword,glance,reading,story,cards,end,sources,build,covart,verse
from fx import *
import math
PG.configure('/festivals/ugadi/',[('','Ugādi','The New Year of the Deccan')],'navy','Ugādi','Lord','Ugādi')
PG.CFG.update(backurl='/festivals/',backname='all festivals')
PG.OUT='outd/ugadi/'
i=0
def toran(w=440,y=10): return f'<path d="M0 {y} h{w}" stroke="#6a4a2a" stroke-width="3"/>'+''.join(f'<path d="M{x} {y} q-6 18 0 30 q6 -12 0 -30z" fill="#2f7a3a"/>' for x in range(10,w,22))
def brahma(): return god('#c0392b')+'<circle cx="-12" cy="-40" r="7" fill="#f2c79b"/><circle cx="12" cy="-40" r="7" fill="#f2c79b"/>'
def neem(): return '<path d="M0 0 v-40" stroke="#2f7a3a" stroke-width="2"/>'+''.join(f'<ellipse cx="{(-1)**k*9}" cy="-{6+k*5}" rx="7" ry="3" fill="#3a9a4a" transform="rotate({(-1)**k*30} {(-1)**k*9} -{6+k*5})"/>' for k in range(7))+'<circle cy="-44" r="3" fill="#fff"/><circle cx="4" cy="-42" r="2.5" fill="#fff"/>'
def jaggery(): return '<path d="M-12 0 l4 -16 h16 l4 16z" fill="#b5651d"/>'
def mango(): return '<path d="M0 0 q-14 -6 -10 -24 q8 -10 16 -2 q6 12 -6 26z" fill="#9ccc3c"/>'
def scroll(): return '<rect x="-30" y="-36" width="60" height="40" rx="3" fill="#fff8e7"/><path d="M-22 -26 h44 M-22 -18 h44 M-22 -10 h30" stroke="#888" stroke-width="2"/>'
def wheel60():
    o='<circle r="60" fill="#fff8e7"/>'
    for k in range(60):
        a=k*6*math.pi/180; o+=f'<path d="M{50*math.cos(a):.1f} {50*math.sin(a):.1f} L{60*math.cos(a):.1f} {60*math.sin(a):.1f}" stroke-width="{3 if k%5==0 else 1}"/>'
    return o+'<circle r="18" fill="#e0a800"/>'
def six(): return [(neem(),1.3),(jaggery(),1.6),(mango(),1.6),('<circle r="10" fill="#7a3a1a"/>',1.2),('<path d="M-12 0 q12 -30 24 0z" fill="#c0392b"/>',1.2),('<rect x="-10" y="-16" width="20" height="16" fill="#fff" />',1.2)]
COV=covart('A doorway with a mango-leaf toraṇa, a plate of neem and jaggery, and the sunrise of the first day',f'<rect width="440" height="196" fill="#fde9c8"/>'+g(220,150,1.4,sun(26))+'<rect y="150" width="440" height="46" fill="#e9d6c0"/>'+'<rect x="40" y="20" width="18" height="176" fill="#8a5a3a"/><rect x="382" y="20" width="18" height="176" fill="#8a5a3a"/>'+g(0,0,1,toran(440,20))+g(150,190,1.3,plate())+g(140,178,1,neem())+g(165,184,1,jaggery())+g(300,190,1.4,kalasha())+g(220,150,.9,rangoli()))
pp=[foreword(i,['In Karnataka, Andhra and Telaṅgāṇa the year begins on <b>Ugādi</b>, the first day of the bright fortnight of Caitra. Doors get fresh mango-leaf garlands, everyone takes an oil bath, the house eats a pinch of <b>bēvu-bella</b> (neem and jaggery, bitter and sweet together), the kitchen makes hōḷige, and in the evening the new year’s almanac is read aloud.','This article explains the name and the day, the Purāṇic claim that Brahmā created the world at this sunrise, the sixty-year cycle of year names, every custom of the day with its meaning, the verse said over the neem, how the solar new year differs in Tuḷunāḍu, and the festivals of the same day across India.'],[('z','Is Ugādi Karnataka’s New Year’s Day?'),('b','The lunar one, Zappy, the one most of Karnataka keeps. The coast keeps a solar one a few weeks later. We’ll do both.')]),
 glance([('Name','Ugādi (Kannada, Telugu), Yugādi; formally Saṃvatsarādi, “the start of the year”'),('When','Caitra Śukla Pratipadā: first day of the bright fortnight of Caitra; March–April'),('Calendar','Cāndramāna (lunar); solar (Sauramāna) new year falls at Meṣa Saṅkrānti, kept in Tuḷunāḍu as Bisu'),('Meaning','Brahmā began creation on this day (Nārada and Brahma Purāṇas)'),('Customs','Oil bath, mango-leaf toraṇa, new clothes, bēvu-bella, hōḷige, pañcāṅga-śravaṇa'),('Same day','Guḍhī Pāḍvā (Maharashtra, Goa), Ceṭī Cand (Sindhi), Sajibu Cheiraoba (Manipur), Nyepi (Bali)'),('Begins','Vasanta Navarātri, ending on '+L('/festivals/rama-navami/','Rāma Navamī'))],svg(560,140,'A mango-leaf garland over the rising sun',f'<rect width="560" height="140" fill="#fde9c8"/>'+g(280,120,1.4,sun(26))+toran(560,10)+'<rect y="118" width="560" height="22" fill="#e9d6c0"/>')),
 reading('name','THE NAME AND THE DAY','Yuga + ādi',svg(560,160,'The moon growing from the new moon to a thin crescent on the first day',f'<rect width="560" height="160" fill="#20243a"/>'+''.join(f'<circle cx="{80+k*100}" cy="70" r="22" fill="{NIGHT}" stroke="#cfd8e6" stroke-width="2"/>' for k in range(5))+'<path d="M180 48 a22 22 0 0 1 0 44 a16 22 0 0 0 0 -44z" fill="#fff8d0" stroke="none"/>'+lab(80,120,'new moon').replace('#111','#fff8d0')+lab(180,120,'Pratipadā').replace('#111','#fff8d0')),['<b>The word.</b> <i>Yuga</i> is an age or a span of time and <i>ādi</i> a beginning: <b>Yugādi</b>, contracted to Ugādi, is “the beginning of the era”. Texts call it <b>Saṃvatsarādi</b>, the beginning of the year.','<b>The day.</b> It is the first lunar day (<b>pratipadā</b>) of the bright fortnight of <b>Caitra</b>, the first month. In the amānta calendar the month starts at the new moon, so the year starts the morning after the last new moon of Phālguna, about two weeks after '+L('/festivals/holi/','Holi')+'.','<b>Why it moves.</b> Twelve lunar months make about 354 days, eleven short of the solar year, so Ugādi drifts back each year until an extra month (<i>adhika māsa</i>) pulls it forward again. It always lands at the start of spring, <b>Vasanta ṛtu</b>.','<b>Two new years in Karnataka.</b> Most of the state keeps the lunar (<b>Cāndramāna</b>) Ugādi. Coastal and some southern communities follow the solar (<b>Sauramāna</b>) year, which starts when the sun enters Aries: Bisu in Tuḷunāḍu, Viṣu in Kerala, Puthāṇḍu in Tamil Nadu.'],[('z','So Ugādi and Viṣu are both new years?'),('b','Two clocks, Zappy: one runs by the moon, one by the sun. Karnataka owns both, inland and on the coast.')],'The year begins <b>with the new crescent</b>.'),
 verse('v-srishti','Nārada Purāṇa','Brahmā began the world at this sunrise',['caitre māsi jagad brahmā sasarja prathame ’hani','śuklapakṣe samagraṃ vai tadā sūryodaye sati'],svg(200,150,'Brahmā seated on a lotus with the sun rising behind',f'<rect width="200" height="150" fill="#fde9c8"/>'+g(100,70,1.3,sun(28))+g(100,140,1.1,lotus())+g(100,128,1,brahma())),'In the month of Caitra, on the first day, in the bright fortnight, at sunrise, Brahmā created the whole world.',[('caitre māsi','in the month of Caitra'),('sasarja','created'),('prathame ’hani','on the first day'),('śukla-pakṣe','in the bright fortnight'),('samagram','the whole'),('sūryodaye','at sunrise')],'<b>Sṛṣṭyādi.</b> This is the verse behind the idea that Ugādi is the birthday of creation. The Nārada Purāṇa gives it in its section on the lunar days, and the Brahma Purāṇa is quoted by medieval digests for the same claim. So the year’s first act is to remember the first act of all, and the day is counted among the most auspicious for beginnings.',k='The world began <b>this morning</b>.',note='Text: Nārada Purāṇa, Pūrva Bhāga 4.110.5, as given on vedapath.app (which prints “sasaja”, read here as sasarja). Editions and numbering differ.'),
 story('creation','BRAHMĀ BEGINS','The first morning, as the Purāṇas tell it',strip('Three panels: a lotus rising from Viṣṇu’s navel; Brahmā on the lotus opening his eyes; the world appearing with sun, mountains and creatures',[panel([(sheshashayi(),.7)],'#dfe9f6',150),panel([(lotus(),1.4),(brahma(),.9)],'#fde9c8',150),panel([(mountain(),.8),(sun(14),1),(cow(),.6)],'#e3f5e9',150)],['the lotus rises','Brahmā wakes','the world appears']),'A Purāṇic creation in brief; details differ from text to text.',['At the end of a cosmic night, Viṣṇu lay on the serpent Śeṣa on the waters, and the whole universe rested inside him.','From his navel rose a lotus, and on the lotus sat <b>Brahmā</b>, four-faced, looking in every direction and seeing only water.','Told to create, Brahmā performed tapas; with the knowledge so gained he arranged the worlds anew: earth and sky, mountains and rivers, time with its days and months.','He brought forth the sages, the gods and all beings, and set time running with its cycles of years and ages (<b>yugas</b>).','The Purāṇas say this new start of time fell on Caitra Śukla Pratipadā at sunrise. Every Ugādi, the tradition says, the world is a year older and begins again.'],[('z','So Ugādi is the world’s birthday?'),('b','By the Purāṇic count, Zappy. A good day to begin anything: a book, a habit, a promise.')],'Each year <b>begins like the first</b>.'),
 reading('sixty','THE SIXTY YEARS','Every year has a name',svg(560,170,'A wheel of sixty divisions, with Jupiter and the sun at the centre',f'<rect width="560" height="170" fill="#fffaf0"/>'+g(170,85,1.2,wheel60())+lab(170,90,'60')+''.join(lab(400,40+k*22,t) for k,t in enumerate(['1 Prabhava','2 Vibhava','3 Śukla','…','60 Akṣaya'])) ),['<b>Names, not numbers.</b> The Deccan calendar names its years from a cycle of <b>sixty</b>, from <b>Prabhava</b>, Vibhava, Śukla… to <b>Akṣaya</b>, and then starts again. Each Ugādi people wish each other a happy new year by name: “the year of Viśvāvasu”, “the year of Parābhava”.','<b>Why sixty.</b> The cycle comes from Jupiter (Bṛhaspati), which takes about twelve years to go round the zodiac; five Jupiter rounds make sixty. In the south the names now run on with the lunar year from Ugādi to Ugādi.','<b>A lifetime.</b> Sixty years is one full turn: completing it is celebrated as <b>ṣaṣṭyabdapūrti</b>, when a person is said to be “born again” into the same year-name as at birth.','<b>The year counts.</b> The pañcāṅga also gives the year in the <b>Śālivāhana Śaka</b> era, which Karnataka’s almanacs follow; its years are counted from the same Caitra new year. (Tradition links the era to King Śālivāhana; historians date its start to 78 CE.)'],[('z','So there’s a year with my name coming back?'),('b','At sixty, Zappy. Your grandparents probably had a little ceremony for it.')],'Sixty names, <b>one wheel</b>.'),
 reading('morning','THE UGĀDI MORNING','Toraṇa, oil bath and new clothes',svg(560,170,'A mother oiling a child’s hair, a doorway with mango leaves and a rangoli',f'<rect width="560" height="170" fill="#fde9c8"/>'+toran(560,8)+'<rect y="140" width="560" height="30" fill="#e9d6c0"/>'+g(150,150,1.1,mother())+g(220,150,.95,child())+g(380,150,.9,rangoli())+g(490,150,1.2,lamp())),['<b>The door.</b> Homes are washed, the threshold smeared with cow-dung or washed clean, and a fresh <b>toraṇa</b> of mango leaves (and often neem and marigold) is tied over the door. A rangoli (<i>raṅgōli</i>) is drawn at the step.','<b>The oil bath.</b> As at Dīpāvali, everyone has an <b>abhyaṅga</b>: warm oil on the head, then a hot bath, the children first. Then new clothes, a visit to the shrine and the elders’ feet.','<b>The pūjā.</b> The family worships its deity, and many place the new almanac before the shrine to be worshipped before it is read. The day begins <b>Vasanta Navarātri</b>, the spring nine nights that end on Rāma Navamī.','<b>Charity.</b> Many give a water-pot or a fan, a <i>prapā</i> (water-booth), or food, since summer is coming. Old texts count gifts on Saṃvatsarādi as especially meritorious.'],[('z','Another oil bath?'),('b','Dīpāvali, Ugādi, birthdays: every new beginning in Karnataka starts with oil and hot water, Zappy.')],'Clean door, <b>clean head</b>.'),
 verse('v-nimba','The bēvu-bella verse','Said before eating the neem',['śatāyur vajradehatvaṃ sarvasampatpradaṃ tathā','sarvāriṣṭaharaṃ kurve nimbapatrāśanaṃ śubham'],svg(200,150,'A small plate of neem flowers and jaggery',ground(200,150,120,'#fde9c8')+g(100,130,1.6,plate())+g(85,118,1.4,neem())+g(120,124,1.2,jaggery())),'For a life of a hundred years, a body strong as a thunderbolt, every kind of wealth, and the removal of every misfortune, I eat the auspicious neem leaf.',[('śatāyuḥ','a hundred years of life'),('vajra-dehatvam','a body like the thunderbolt'),('sarva-sampat','all prosperity'),('ariṣṭa','misfortune, ill omen'),('nimba-patra','neem leaf'),('aśanam','eating')],'<b>Bitter first.</b> Before any sweet, the family eats a pinch of <b>bēvu-bella</b>: neem flowers or tender leaves with jaggery, in many homes with tamarind, pepper, salt and raw mango too. The verse treats the neem as medicine for the year; the jaggery makes it bearable. The meaning everyone gives children: the year will bring both, take both with the same face.',k='Take the bitter <b>with the sweet</b>.',note='A household verse, as printed in popular collections (e.g. hindupad.com) with small variations; we have not traced it to one text.'),
 cards('tastes','SIX TASTES','Bēvu-bella and Ugādi pacchaḍi',fig_row('Neem, jaggery, raw mango, tamarind, chilli and salt',six(),['neem','jaggery','mango','tamarind','chilli','salt'],gy=150),[('🌿','Karnataka','<b>Bēvu-bella</b>: at its simplest neem and jaggery; many homes grind in tamarind, pepper or chilli, salt and raw mango, making six tastes.'),('🥣','Andhra and Telaṅgāṇa','<b>Ugādi pacchaḍi</b>: the same six tastes in a liquid dish, drunk from a cup after the morning pūjā.'),('🧭','What each means','Popular readings: neem for sorrow, jaggery for joy, tamarind for disgust, chilli for anger, salt for fear, mango for surprise. The lesson is one: accept them all. (Popular interpretation.)'),('🩺','Season','Āyurveda sees the turn to summer as a time to balance the body; neem is a traditional seasonal bitter. Treat this as tradition, not prescription.')],[('z','Do I have to eat the bitter part?'),('b','Just a pinch, Zappy, with a lot of jaggery. It’s a promise, not a punishment.')],'<b>Six tastes</b>, one year.'),
 reading('kitchen','THE UGĀDI KITCHEN','Hōḷige, mango and the day after',fig_row('A stack of hōḷige, mango chitranna, payasa and a plantain leaf',[(laddu('#e0a800'),1.6),(mango(),1.8),(pot_rice(),1.3),(banana(),1.6)],['hōḷige','māvina chitrānna','pāyasa','bāḷe ele'],gy=150),['<b>Hōḷige.</b> The day’s sweet in most of Karnataka is <b>hōḷige</b> or obbaṭṭu: a thin flatbread stuffed with cooked gram dal and jaggery, eaten hot with ghee or with sweet coconut milk (<i>kāyi hāḷu</i>). In Andhra it is bobbaṭlu.','<b>The first mango.</b> Raw mango arrives with Ugādi: <b>māvinakāyi chitrānna</b> (mango rice), fresh mango pickles, and mango in the bēvu-bella. Many homes eat no new mango until it is first offered on Ugādi.','<b>The meal.</b> A festive meal on a plantain leaf: kosambari, palya, huḷi or sāru, pāyasa, hōḷige, bhakṣya. In the north of the state jōḷada rotti may join the plate.','<b>Hosa toḍaku.</b> In Old Mysore and parts of southern Karnataka the day after Ugādi is <b>hosa toḍaku</b>, “the new beginning”, when many families who eat meat have their festive meal, and old friends play cards for small stakes. Customs vary widely.'],[('z','Why is hōḷige always the festival sweet?'),('b','Dal for strength, jaggery for joy, ghee for richness, Zappy. And it takes a whole morning, which is how you know it’s a festival.')],'Mango, jaggery, <b>and ghee</b>.'),
 reading('panchanga','PAÑCĀṄGA-ŚRAVAṆA','Listening to the year',svg(560,170,'An elder reading an almanac to a seated family under a lamp',f'<rect width="560" height="170" fill="#fde9c8"/>'+'<rect y="140" width="560" height="30" fill="#e9d6c0"/>'+g(160,150,1.2,sage('#ff8c1a'))+g(220,126,1,scroll())+''.join(g(x,150,.9,person(c,seat=True)) for x,c in [(320,'#c0392b'),(380,'#2a5aa8'),(440,'#2a9d6f')])+g(500,150,.9,child())),['<b>The almanac read aloud.</b> In the evening, at a temple or at home, a priest or elder reads from the new <b>pañcāṅga</b>: the year’s name, its king and minister among the planets, the expected rains and harvests, eclipses, the good days for weddings and work. This is <b>pañcāṅga-śravaṇa</b>, “hearing the almanac”, and hearing it is itself counted a merit.','<b>Five limbs.</b> <i>Pañca-aṅga</i> means five limbs: tithi (lunar day), vāra (weekday), nakṣatra (lunar mansion), yoga and karaṇa. Read our '+L('/festivals/panchanga/','Pañcāṅga article')+' for how each works.','<b>Your own forecast.</b> Many listen for their own rāśi: the reader gives each sign’s “income and expenditure” and “honour and dishonour” for the year in simple numbers, which families compare with amusement.','<b>Gifts.</b> The reader is given a new cloth, fruit and dakṣiṇā; in villages the reading was a public event in the temple square.'],[('z','Do people believe the forecasts?'),('b','Some do, some smile, Zappy. Everyone listens. It’s the year being welcomed out loud.')],'The year is <b>read aloud</b>.'),
 cards('india','THE SAME DAY ACROSS INDIA','Guḍhī Pāḍvā, Ceṭī Cand and more',fig_row('A gudhi pole with cloth and a pot, a lamp, a sun and a lotus',[('<path d="M0 0 v-90" stroke="#6a4a2a" stroke-width="4"/><path d="M0 -84 l-14 30 h28z" fill="#e0a800"/>'+g(0,-88,.6,pot('#c98a5a')),1),(lamp(),1.6),(sun(20),1),(lotus(),1.6)],['guḍhī','lamp','Sauramāna','Vasanta'],gy=150),[('🚩','Maharashtra and Goa','<b>Guḍhī Pāḍvā</b>: a pole topped with a silk cloth, neem, a garland and an upturned pot is raised at the window as a banner of victory; shrīkhaṇḍ and puran poḷi are eaten.'),('🌊','Sindhis','<b>Ceṭī Cand</b>, the new year and the birthday of Jhūlelāl.'),('🌕','Manipur and Bali','<b>Sajibu Cheiraoba</b> in Manipur; in Bali, Indonesia, the Śaka new year is <b>Nyepi</b>, a day of silence.'),('☀️','Solar new years','A few weeks later, at Meṣa Saṅkrānti: Bisu in Tuḷunāḍu, Viṣu in Kerala, Puthāṇḍu in Tamil Nadu, Vaisākhī in Punjab, Pohela Boishakh in Bengal.')],[('z','A day of silence for New Year?'),('b','In Bali, Zappy: no lights, no travel, no noise. A different way to begin.')],'One spring, <b>many new years</b>.'),
 reading('history','UGĀDI IN KARNATAKA’S HISTORY','Kings, grants and poets',svg(560,150,'A stone inscription slab, a temple and a book',f'<rect width="560" height="150" fill="#fffaf0"/>'+'<rect y="120" width="560" height="30" fill="#e9d6c0"/>'+'<path d="M120 125 v-90 q30 -20 60 0 v90z" fill="#a8a29a"/>'+''.join(f'<path d="M128 {50+k*12} h44" stroke="#666" stroke-width="2"/>' for k in range(6))+g(300,125,1,palace())+g(460,110,1.4,book())),['<b>In stone.</b> Inscriptions of the Cāḷukyas, Kākatīyas and the Vijayanagara kings record land grants and endowments made on Yugādi, the start of the year being an auspicious day to give.','<b>The court.</b> Vijayanagara and later the Mysuru court kept the new year with a public reading of the almanac and gifts; the year’s name headed royal documents.','<b>The poets.</b> Ugādi is a favourite of Kannada poetry: D. R. Bēndre’s song on Yugādi, about the new year that comes back age after age bringing new life with it, is sung in every Karnataka school and on radio each year.','<b>Today.</b> The day is a public holiday in Karnataka, Andhra and Telaṅgāṇa; newspapers carry the year’s pañcāṅga summary, and temples hold the reading in their courtyards.'],[('z','Which song is that?'),('b','Bēndre’s “Yugādi”, Zappy. Ask any Kannadiga to sing it; they won’t need the words.')],'A festival <b>written in stone</b>.'),
 reading('meaning','WHAT UGĀDI MEANS','Beginning again',svg(560,150,'A sprouting seed beside the rising sun',f'<rect width="560" height="150" fill="#fde9c8"/>'+g(280,110,1.4,sun(26))+'<rect y="120" width="560" height="30" fill="#e9d6c0"/>'+g(150,122,1.6,'<path d="M0 0 v-30" stroke="#2f7a3a" stroke-width="3"/><path d="M0 -24 q-16 -10 -20 -24 q14 2 20 18z M0 -28 q16 -8 18 -22 q-14 2 -18 16z" fill="#3a9a4a"/>')+g(420,122,1.6,neem())),['<b>Every year is new.</b> If the world began at this sunrise, each Ugādi is a fresh start offered to everyone: the old year’s debts are cleared, quarrels mended, new books opened. Many make their resolutions on Ugādi rather than in January.','<b>Bitter and sweet.</b> The neem and jaggery are the festival’s whole teaching in a pinch: what comes will be mixed; receive it steadily. Many teachers compare it with the Gītā’s call to equanimity in pleasure and pain (2.38). (Interpretation.)','<b>Listening.</b> The evening ends with hearing: the almanac, the elders, the year’s name. Ugādi asks us to begin by listening.','<b>Spring.</b> The mango flowers, the neem blossoms, the koel calls. The festival is the season itself, received as a gift.'],[('z','If I could do one thing for Ugādi?'),('b','Eat the bēvu-bella with a smile, Zappy, and start one good thing you’ve been putting off. Today, not Monday.')],'Begin again, <b>bitter and sweet</b>.'),
 end(i,['<b>When.</b> Caitra Śukla Pratipadā, the first day of the lunar year.','<b>Why.</b> Brahmā began creation at this sunrise (Nārada Purāṇa).','<b>Name.</b> Each year named from a sixty-year cycle.','<b>Customs.</b> Toraṇa, oil bath, bēvu-bella, hōḷige, the almanac read aloud.','<b>Elsewhere.</b> Guḍhī Pāḍvā; the solar new years, Bisu and Viṣu, a few weeks later.'],'Previous: '+L('/festivals/holi/','Holi')+'. Next: '+L('/festivals/rama-navami/','Rāma Navamī')+', nine days later.','Ugādi: the new year of the Deccan'),
 sources([('Texts:','Nārada Purāṇa, Pūrva Bhāga 4.110.5 (Brahmā creates on Caitra Śukla Pratipadā), as on vedapath.app; Brahma Purāṇa as cited for Sṛṣṭyādi (via Wikipedia, “Ugadi”). Bēvu-bella verse from popular collections (hindupad.com).'),('Customs and history:','Wikipedia, “Ugadi” (Saṃvatsarādi, pañcāṅga-śravaṇa, six tastes, regional foods, inscriptions of Cāḷukyas, Kākatīyas, Vijayanagara, related new years, Sauramāna Ugādi).')],'the meanings assigned to each of the six tastes (popular); hosa toḍaku customs (vary by region and family); the Śālivāhana link (tradition); details of court observances (general tradition); the exact wording of the bēvu-bella verse.','Verses in IAST; numbering as in the cited editions.')]
build(i,'NEW YEAR · NEEM AND JAGGERY · THE FIRST SUNRISE',COV,'The first morning of the year','The <b>day</b> and its name, the <b>creation</b> it remembers, the <b>sixty years</b>, every custom from toraṇa to <b>bēvu-bella</b> and the almanac, with the verses, and Karnataka’s two new years.','Ugādi explained: Caitra Śukla Pratipadā, Brahmā’s creation (Nārada Purāṇa verse), the sixty-year cycle, the oil bath and mango toraṇa, the bēvu-bella verse and six tastes, hōḷige, pañcāṅga-śravaṇa, Guḍhī Pāḍvā and the solar new years of Karnataka’s coast.',pp)
